/* ==========================================================
   AutoBI 16.1.1.15 - ẨN GIAO DIỆN AN TOÀN
   Chỉ display:none; KHÔNG xóa node / KHÔNG sửa logic lõi.
   ========================================================== */
(function () {
    'use strict';

    const css = `
        #btn-menu-tools,
        #btn-menu-plan,
        .btn-tutorial-link,
        .tgdd-chk-group:has(#chk-test) {
            display: none !important;
        }
    `;

    try {
        if (typeof GM_addStyle === 'function') GM_addStyle(css);
        else {
            const st = document.createElement('style');
            st.textContent = css;
            (document.head || document.documentElement).appendChild(st);
        }
    } catch (_) {}

    function applySafeHide(root = document) {
        try {
            root.querySelectorAll('#btn-menu-tools, #btn-menu-plan, .btn-tutorial-link').forEach(el => {
                el.style.setProperty('display', 'none', 'important');
            });

            const chk = root.querySelector('#chk-test');
            if (chk) {
                const row = chk.closest('.tgdd-chk-group') || chk.parentElement;
                if (row) row.style.setProperty('display', 'none', 'important');
            }
        } catch (_) {}
    }

    const run = () => applySafeHide(document);
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', run, { once: true });
    } else run();

    let hideQueued = false;
    const scheduleSafeHide = () => {
        if (hideQueued) return;
        hideQueued = true;
        setTimeout(() => {
            hideQueued = false;
            run();
        }, 180);
    };
    new MutationObserver(scheduleSafeHide).observe(document.documentElement, { childList: true, subtree: true });
})();

/* ==========================================================
   AutoBI 16.1.1.5 - AUTH RIÊNG
   - Chỉ chuyển bước kiểm tra quyền chính sang Apps Script riêng.
   - Giữ nguyên cache Auth và các chức năng khác của bản Stable.
   ========================================================== */
(function () {
    const PRIVATE_AUTH_API = 'https://script.google.com/macros/s/AKfycbzSGNHjQ81dzQJcvk9m1lubSDvkn2bQ2qpSyALpmKqyCBSQXtIH_j3738YLVhIjlxGg/exec';
    const OLD_AUTH_SHEET_ID = '1iuApMwdKYx9ofo0oJR84AlzXka0PmTQPudXzx0Uub0o';
    const nativeRequest = GM_xmlhttpRequest;

    GM_xmlhttpRequest = function (details) {
        try {
            const url = String(details && details.url || '');
            const isMainAuthCheck =
                url.includes('docs.google.com/spreadsheets/d/' + OLD_AUTH_SHEET_ID + '/export') &&
                url.includes('gid=0') &&
                Number(details.timeout || 0) === 8000;

            if (!isMainAuthCheck) return nativeRequest(details);

            const m = url.match(/[?&]_t=([^&]+)/);
            // User ID is not present in the legacy CSV URL, so obtain it from the page text.
            const pageText = (document.body && document.body.innerText) || '';
            const userMatch = pageText.match(/(?:Người dùng\s*:\s*)?(\d{4,})\s*[-–]/i) || pageText.match(/\b(\d{4,})\b/);
            const userId = userMatch ? userMatch[1] : '';

            if (!userId) return nativeRequest(details);

            return nativeRequest({
                method: 'GET',
                url: PRIVATE_AUTH_API + '?type=check_auth&user=' + encodeURIComponent(userId) + '&_t=' + (m ? m[1] : Date.now()),
                timeout: details.timeout || 8000,
                onload: function (res) {
                    try {
                        const data = JSON.parse(res.responseText || '{}');
                        if (data.status === 'success' && data.authorized === true) {
                            // Chuyển JSON riêng thành CSV giả để lõi AutoBI cũ xử lý nguyên vẹn.
                            const name = String(data.name || '').replace(/"/g, '""');
                            const exp = (data.expireDays === null || data.expireDays === undefined) ? '' : data.expireDays;
                            const csv = 'UserID,Name,C,D,E,F,G,H,ExpireDays\n' +
                                        String(data.user || userId) + ',"' + name + '",,,,,,,' + exp;
                            return details.onload && details.onload({
                                status: 200,
                                responseText: csv,
                                finalUrl: res.finalUrl || PRIVATE_AUTH_API
                            });
                        }
                        return details.onload && details.onload({ status: 200, responseText: 'UserID,Name,C,D,E,F,G,H,ExpireDays\n' });
                    } catch (e) {
                        if (details.onerror) details.onerror(e);
                    }
                },
                onerror: details.onerror,
                ontimeout: details.ontimeout
            });
        } catch (e) {
            return nativeRequest(details);
        }
    };
})();



/* ==========================================================
   AutoBI Stable Loader 16.1.1.2
   - Không thay đổi dữ liệu / cấu hình / cách tính của AutoBI gốc.
   - Chỉ thay 3 điểm chờ cố định trong quy trình Thi đua bằng
     cơ chế đợi bảng BI tải xong và ổn định rồi mới scrape.
   ========================================================== */
window.__AutoBIStable = window.__AutoBIStable || (function () {
    function isLoading() {
        const selectors = [
            '.ant-spin-spinning',
            '.loading',
            '.spinner',
            '[aria-busy="true"]',
            '.animate-spin'
        ];
        return selectors.some(sel => {
            const els = document.querySelectorAll(sel);
            return Array.from(els).some(el => {
                const st = getComputedStyle(el);
                const r = el.getBoundingClientRect();
                return st.display !== 'none' &&
                       st.visibility !== 'hidden' &&
                       st.opacity !== '0' &&
                       r.width > 0 && r.height > 0;
            });
        });
    }

    function tableSignature() {
        const tables = Array.from(document.querySelectorAll(
            '.report-table table, .ant-table-content table'
        ));
        if (!tables.length) return '';

        // Chỉ lấy lượng text vừa đủ để phát hiện bảng đã đổi,
        // tránh đọc toàn DOM nặng mỗi lần poll.
        return tables.slice(0, 40).map((t, i) => {
            const head = (t.querySelector('thead')?.innerText || '').trim().slice(0, 220);
            const rows = Array.from(t.querySelectorAll('tbody tr'))
                .filter(r => !r.classList.contains('ant-table-measure-row'))
                .slice(0, 4)
                .map(r => (r.innerText || '').trim().slice(0, 180))
                .join('|');
            return i + ':' + head + '::' + rows;
        }).join('###');
    }

    function wait(callback, options) {
        options = options || {};
        const minWait = options.minWait ?? 900;
        const maxWait = options.maxWait ?? 9000;
        const poll = options.poll ?? 250;
        const requireChange = !!options.requireChange;

        const started = Date.now();
        const firstSig = tableSignature();
        let lastSig = firstSig;
        let stableCount = 0;
        let sawLoading = isLoading();
        let sawChange = false;
        let finished = false;

        function done(reason) {
            if (finished) return;
            finished = true;
            clearInterval(timer);
            console.log('[AutoBI Stable] ✅ Tiếp tục:', reason,
                        '| thời gian chờ:', Date.now() - started, 'ms');
            try { callback(); }
            catch (e) {
                console.error('[AutoBI Stable] Callback lỗi:', e);
                throw e;
            }
        }

        const timer = setInterval(() => {
            const elapsed = Date.now() - started;
            const loading = isLoading();
            if (loading) sawLoading = true;

            const sig = tableSignature();
            if (sig && sig !== firstSig) sawChange = true;

            if (sig && sig === lastSig && !loading) stableCount++;
            else stableCount = 0;

            lastSig = sig;

            // Bảng tồn tại + hết loading + ổn định qua nhiều nhịp.
            // Với drill-down ưu tiên phải thấy bảng thay đổi.
            const changedEnough = !requireChange || sawChange || sawLoading || elapsed >= 2200;
            if (elapsed >= minWait && sig && !loading && stableCount >= 3 && changedEnough) {
                done('bảng đã ổn định');
                return;
            }

            // Không để tool treo vô hạn nếu BI có thay đổi giao diện.
            if (elapsed >= maxWait) done('hết thời gian chờ - chạy fallback');
        }, poll);

        return timer;
    }

    return { wait };
})();

window.__AutoBIStableWait = function (callback, legacyDelay) {
    // legacyDelay được giữ lại để patch an toàn cú pháp, nhưng không còn
    // dùng làm thời gian chờ cứng.
    return window.__AutoBIStable.wait(callback, {
        minWait: 900,
        maxWait: 9000,
        poll: 250,
        requireChange: false
    });
};

window.__AutoBIStableWaitDetail = function (callback, legacyDelay) {
    return window.__AutoBIStable.wait(callback, {
        minWait: 1000,
        maxWait: 10000,
        poll: 250,
        requireChange: true
    });
};



/* ==========================================================
   AutoBI Health Detail Fix 16.1.1.10
   - Bản 16.1.1.7 chỉ lưu Sức khỏe ST vào link8_health.total.
   - Bản này quét thêm từng siêu thị và lưu:
       link8_health.shop1 ... link8_health.shop5
   ========================================================== */
window.__AutoBIHealthPerShop = window.__AutoBIHealthPerShop || (function () {
    const DATA_KEY = 'tgdd_data_cache_v30';

    const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

    function visible(el) {
        if (!el) return false;
        const st = getComputedStyle(el);
        const r = el.getBoundingClientRect();
        return st.display !== 'none' &&
               st.visibility !== 'hidden' &&
               st.opacity !== '0' &&
               r.width > 0 && r.height > 0;
    }

    function slug(v) {
        return String(v || '')
            .normalize('NFD')
            .replace(/[\u0300-\u036f]/g, '')
            .toLowerCase()
            .replace(/đ/g, 'd')
            .replace(/[^a-z0-9]/g, '');
    }

    function findFilterButton(label) {
        const want = slug(label);
        return Array.from(document.querySelectorAll('button.filter-field-card, button'))
            .find(btn => {
                if (!visible(btn)) return false;
                const spans = Array.from(btn.querySelectorAll('span'));
                if (spans.some(s => slug(s.innerText || s.textContent) === want)) return true;
                return slug(btn.innerText || btn.textContent) === want;
            }) || null;
    }

    function findReloadButton() {
        return Array.from(document.querySelectorAll('button')).find(btn => {
            if (!visible(btn)) return false;
            const t = slug(btn.innerText || btn.textContent);
            return t.includes('tailai') ||
                   btn.querySelector('.lucide-rotate-cw, [data-lucide="rotate-cw"]');
        }) || null;
    }

    function getVisibleFilterPanel() {
        // Cách 1: các popup/dropdown phổ biến.
        const common = Array.from(document.querySelectorAll(
            '.ant-popover, .ant-dropdown, .ant-select-dropdown, [role="dialog"], [role="listbox"], .dropdown-menu, .popover'
        )).filter(visible);

        // Cách 2: BI hiện tại dùng popup riêng. Tìm container nhỏ nhất có
        // "Chọn tất cả" + "Bỏ chọn tất cả" + ít nhất một dòng siêu thị.
        const semantic = Array.from(document.querySelectorAll('div, section, aside, ul'))
            .filter(visible)
            .filter(el => {
                const t = slug(el.innerText || el.textContent);
                return t.includes('chontatca') &&
                       t.includes('bochontatca') &&
                       (t.includes('sieuthi') || /\d{4}/.test(el.innerText || ''));
            });

        const candidates = [...common, ...semantic];
        let best = null;
        let bestScore = -Infinity;

        for (const el of candidates) {
            const raw = String(el.innerText || el.textContent || '');
            const txt = slug(raw);
            const boxes = el.querySelectorAll('input[type="checkbox"]').length;
            const rect = el.getBoundingClientRect();

            let s = 0;
            if (txt.includes('chontatca')) s += 100;
            if (txt.includes('bochontatca')) s += 100;
            if (txt.includes('bochondangloc')) s += 40;
            if (boxes) s += boxes * 20;
            if (/\b5243\b/.test(raw) || /\b8265\b/.test(raw)) s += 80;

            // Ưu tiên container nhỏ nhất chứa đúng popup, tránh chọn cả body/app.
            s -= Math.min((rect.width * rect.height) / 100000, 100);

            if (s > bestScore) {
                bestScore = s;
                best = el;
            }
        }
        return best;
    }

    function clickCheckbox(box, desired) {
        if (!box) return;
        if (!!box.checked !== desired) {
            try { box.click(); } catch (_) {}
        }
    }

    function findTargetCheckbox(panel, tokens) {
        const normalized = tokens.map(slug).filter(Boolean);
        const boxes = Array.from(panel.querySelectorAll('input[type="checkbox"]'));

        let best = null;
        let bestScore = -1;

        for (const box of boxes) {
            const holders = [
                box.closest('label'),
                box.closest('li'),
                box.closest('[role="option"]'),
                box.parentElement,
                box.parentElement && box.parentElement.parentElement
            ].filter(Boolean);

            for (const h of holders) {
                const raw = String(h.innerText || h.textContent || '').trim();
                const s = slug(raw);
                if (!s) continue;

                for (const token of normalized) {
                    if (!token) continue;
                    let score = -1;
                    if (s === token) score = 1000;
                    else if (s.includes(token) || token.includes(s)) {
                        score = 700 - Math.abs(s.length - token.length);
                    }
                    if (score > bestScore) {
                        bestScore = score;
                        best = box;
                    }
                }
            }
        }
        return bestScore >= 500 ? best : null;
    }

    function findShopRow(panel, tokens) {
        const wants = tokens.map(slug).filter(Boolean);
        const nodes = Array.from(panel.querySelectorAll('label, li, [role="option"], div, span'));
        let best = null;
        let bestScore = -1;

        for (const el of nodes) {
            if (!visible(el)) continue;
            const raw = String(el.innerText || el.textContent || '').trim();
            if (!raw || raw.length > 180) continue;
            const s = slug(raw);

            for (const w of wants) {
                let score = -1;
                if (s === w) score = 1000;
                else if (s.includes(w)) score = 850 - Math.abs(s.length - w.length);
                if (score > bestScore) {
                    bestScore = score;
                    best = el;
                }
            }
        }
        return bestScore >= 500 ? best : null;
    }

    async function waitForSingleShop(expectedTokens, timeout = 7000) {
        const wants = expectedTokens.map(slug).filter(Boolean);
        const start = Date.now();

        while (Date.now() - start < timeout) {
            const btn = findFilterButton('Siêu thị');
            const text = slug(btn && (btn.innerText || btn.textContent));
            // Khi chỉ chọn 1 shop, nút thường không còn hiển thị "2 siêu thị".
            if (text && !text.includes('2sieuthi') && !text.includes('2/2')) return true;

            // Fallback: mở popup và xác nhận chỉ có 1 checkbox shop được tick.
            if (btn) {
                try { btn.click(); } catch (_) {}
                await sleep(250);
                const panel = getVisibleFilterPanel();
                if (panel) {
                    const checked = Array.from(panel.querySelectorAll('input[type="checkbox"]:checked'));
                    const shopChecked = checked.filter(box => {
                        const h = box.closest('label') || box.closest('li') ||
                                  box.closest('[role="option"]') || box.parentElement;
                        const raw = String(h && (h.innerText || h.textContent) || '');
                        return /\d{4}/.test(raw);
                    });
                    try { btn.click(); } catch (_) {}
                    if (shopChecked.length === 1) return true;
                } else {
                    try { btn.click(); } catch (_) {}
                }
            }
            await sleep(350);
        }
        return false;
    }

    async function waitBI(maxWait = 10000) {
        await new Promise(resolve => {
            if (window.__AutoBIStable && typeof window.__AutoBIStable.wait === 'function') {
                window.__AutoBIStable.wait(resolve, {
                    minWait: 900,
                    maxWait,
                    poll: 250,
                    requireChange: false
                });
            } else {
                setTimeout(resolve, 2500);
            }
        });
    }

    async function openShopPanel() {
        const btn = findFilterButton('Siêu thị');
        if (!btn) return { ok: false, reason: 'Không tìm thấy bộ lọc Siêu thị' };

        btn.click();
        await sleep(450);

        const panel = getVisibleFilterPanel();
        if (!panel) {
            try { btn.click(); } catch (_) {}
            return { ok: false, reason: 'Không tìm thấy bảng chọn Siêu thị' };
        }

        return { ok: true, btn, panel };
    }

    async function selectSingleShop(config, idx) {
        const opened = await openShopPanel();
        if (!opened.ok) return opened;

        const { btn, panel } = opened;
        const tokens = [
            config['makho' + idx],
            config['shopCode' + idx],
            config['code' + idx],
            config['shop' + idx],
            config['shop' + idx + 'Short']
        ].filter(Boolean);

        // 1. Bỏ chọn tất cả.
        const actions = Array.from(panel.querySelectorAll('button, a, label, div, span')).filter(visible);
        const clearAll = actions
            .filter(el => slug(el.innerText || el.textContent) === 'bochontatca')
            .sort((a,b) => (a.innerText || '').length - (b.innerText || '').length)[0];

        if (clearAll) {
            try { clearAll.click(); } catch (_) {}
            await sleep(500);
        } else {
            const boxes = Array.from(panel.querySelectorAll('input[type="checkbox"]'));
            for (const box of boxes) {
                clickCheckbox(box, false);
                await sleep(30);
            }
        }

        // React có thể dựng lại popup sau khi Bỏ chọn tất cả.
        const freshPanel = getVisibleFilterPanel() || panel;
        let targetBox = findTargetCheckbox(freshPanel, tokens);

        if (targetBox) {
            clickCheckbox(targetBox, true);
        } else {
            // Nếu BI dùng checkbox custom, click trực tiếp dòng "5243 - ... Hải Anh".
            const row = findShopRow(freshPanel, tokens);
            if (!row) {
                try { btn.click(); } catch (_) {}
                return { ok: false, reason: 'Không tìm thấy dòng siêu thị ' + (config['shop' + idx] || idx) };
            }
            try { row.click(); } catch (_) {}
        }

        await sleep(600);
        try { btn.click(); } catch (_) {}
        await sleep(500);

        // 2. Bắt buộc xác nhận bộ lọc đã chuyển về đúng 1 shop.
        const oneShop = await waitForSingleShop(tokens, 8000);
        if (!oneShop) {
            return { ok: false, reason: 'Bộ lọc chưa chuyển về 1 siêu thị' };
        }

        // 3. Tải lại và chờ BI ổn định.
        const reload = findReloadButton();
        if (!reload) return { ok: false, reason: 'Không tìm thấy nút Tải lại' };

        reload.click();
        await waitBI(18000);
        await sleep(1000);
        return { ok: true };
    }

    async function restoreAllShops() {
        const opened = await openShopPanel();
        if (!opened.ok) return false;

        const { btn, panel } = opened;
        const actions = Array.from(panel.querySelectorAll('button, a, label, div, span')).filter(visible);
        const selectAll = actions.find(el => slug(el.innerText || el.textContent) === 'chontatca');

        if (selectAll) {
            try { selectAll.click(); } catch (_) {}
            await sleep(450);
        } else {
            const boxes = Array.from(panel.querySelectorAll('input[type="checkbox"]'));
            for (const box of boxes) {
                clickCheckbox(box, true);
                await sleep(25);
            }
        }

        try { btn.click(); } catch (_) {}
        await sleep(400);

        const reload = findReloadButton();
        if (reload) {
            reload.click();
            await waitBI(12000);
        }
        return true;
    }

    function scrapeAsPromise(scrapeFn) {
        return new Promise(resolve => {
            let finished = false;
            const timer = setTimeout(() => {
                if (!finished) {
                    finished = true;
                    resolve(null);
                }
            }, 90000);

            try {
                scrapeFn(data => {
                    if (finished) return;
                    finished = true;
                    clearTimeout(timer);
                    resolve(data || null);
                });
            } catch (e) {
                clearTimeout(timer);
                finished = true;
                console.error('[AutoBI Health] scrape lỗi:', e);
                resolve(null);
            }
        });
    }

    async function scan(config, scrapeFn, toastFn, done) {
        const shops = [];
        for (let i = 1; i <= 5; i++) {
            if (config && config['shop' + i]) shops.push(i);
        }

        if (!shops.length) {
            if (done) done();
            return;
        }

        console.log('[AutoBI Health] Bắt đầu quét chi tiết', shops.length, 'siêu thị');

        for (let pos = 0; pos < shops.length; pos++) {
            const idx = shops[pos];
            const key = 'shop' + idx;
            const name = config[key] || key;

            if (toastFn) {
                toastFn('🏬 Sức khỏe ST [' + (pos + 1) + '/' + shops.length + ']: ' + name, 2500);
            }

            const selected = await selectSingleShop(config, idx);
            if (!selected.ok) {
                console.warn('[AutoBI Health] Bỏ qua', key, selected.reason);
                continue;
            }

            await window.__AutoBIOnline40.scanShop(config, idx, waitBI, toastFn || console.log);
            // Sau reload có thể BI quay về tab mặc định; scrapeFn sẽ tự mở tab Ngành hàng.
            const data = await scrapeAsPromise(scrapeFn);
            if (!data) {
                console.warn('[AutoBI Health] Không lấy được dữ liệu', key);
                continue;
            }

            const cache = GM_getValue(DATA_KEY, {}) || {};
            if (!cache.link8_health) cache.link8_health = {};
            cache.link8_health[key] = data;
            GM_setValue(DATA_KEY, cache);

            console.log('[AutoBI Health] ✅ Đã lưu', key, name, data);
            await sleep(250);
        }

        if (toastFn) toastFn('🔄 Đang khôi phục bộ lọc tất cả Siêu thị...', 1800);
        try { await restoreAllShops(); } catch (e) {
            console.warn('[AutoBI Health] Không khôi phục được bộ lọc:', e);
        }

        if (done) done();
    }

    return { scan, selectSingleShop, restoreAllShops, waitBI };
})();

/* AutoBI 16.1.1.41 - read installment totals directly from Báo cáo trả chậm. */
window.__AutoBIInstallment41 = (() => {
  const norm = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/đ/gi, 'd').toLowerCase().replace(/[^a-z0-9]/g, '');
  const text = e => (e?.innerText || e?.textContent || '').trim();
  const visible = e => !!e && e.getClientRects().length > 0;
  const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
  const number = s => {
    const raw = String(s ?? '').replace(/,/g, '').replace(/%/g, '').replace(/\s/g, '');
    return /^-?\d+(\.\d+)?$/.test(raw) ? Number(raw) : null;
  };

  function matchShop(label, config) {
    const value = norm(label);
    const matches = [];
    for (let i = 1; i <= 5; i++) {
      const key = 'shop' + i;
      if (!config[key]) continue;
      const candidates = [config[key], config[key + 'Short'], config['makho' + i], config['shopCode' + i]].map(norm).filter(Boolean);
      if (candidates.some(candidate => value === candidate || value.endsWith(candidate) || candidate.endsWith(value))) matches.push(key);
    }
    return matches.length === 1 ? matches[0] : null;
  }

  function read(config, root = document) {
    const rows = {};
    let confirmed = false;
    for (const table of root.querySelectorAll('table')) {
      for (const tr of table.querySelectorAll('tbody tr:not(.ant-table-measure-row)')) {
        const cells = [...tr.querySelectorAll('td')];
        if (cells.length < 8) continue;
        const key = matchShop(text(cells[0]), config);
        if (!key) continue;
        const values = [1, 2, 3, 4, 6].map(index => number(text(cells[index])));
        if (values.some(value => value === null)) continue;
        confirmed = true;
        rows[key] = {dt_tragop: values[0], dt_sieu_thi: values[1], tg: values[2], hc: values[3], fe: values[4]};
      }
    }
    return {confirmed, rows};
  }

  function save(rows) {
    const cache = GM_getValue('tgdd_data_cache_v30', {}) || {};
    cache.link7 ||= {};
    cache.link2 ||= {};
    for (const [key, row] of Object.entries(rows)) {
      cache.link7[key] = {...cache.link7[key], _SHOP_DT: row.dt_sieu_thi, _SHOP_HC: row.hc, _SHOP_FE: row.fe, _SHOP_TOTAL_: row};
      cache.link2[key] = {...cache.link2[key], tg: row.tg};
    }
    const total = Object.values(rows).reduce((sum, row) => ({dt: sum.dt + row.dt_sieu_thi, installment: sum.installment + row.dt_tragop, hc: sum.hc + row.hc, fe: sum.fe + row.fe}), {dt: 0, installment: 0, hc: 0, fe: 0});
    cache.link2.total = {...cache.link2.total, tg: total.dt ? total.installment / total.dt * 100 : 0};
    cache.link7.total = {...cache.link7.total, _SHOP_DT: total.dt, _SHOP_HC: total.hc, _SHOP_FE: total.fe, _SHOP_TOTAL_: {dt_sieu_thi: total.dt, dt_tragop: total.installment, tg: total.dt ? total.installment / total.dt * 100 : 0, hc: total.hc, fe: total.fe}};
    GM_setValue('tgdd_data_cache_v30', cache);
  }

  function callbackTask(start, timeout = 12000) {
    return new Promise(resolve => {
      let complete = false;
      const finish = value => { if (!complete) { complete = true; clearTimeout(timer); resolve(value); } };
      const timer = setTimeout(() => finish(false), timeout);
      try { start(finish); } catch (error) { console.error('[AutoBI Trả chậm 41]', error); finish(false); }
    });
  }

  async function selectAllFilter(label) {
    const wanted = norm(label);
    let button = null;
    for (let attempt = 0; attempt < 30 && !button; attempt++) {
      button = [...document.querySelectorAll('button')].find(item => visible(item) && [...item.querySelectorAll('span')].some(span => norm(text(span)) === wanted));
      if (!button) await sleep(300);
    }
    if (!button) throw new Error('Không tìm thấy bộ lọc ' + label);
    button.click();
    await sleep(700);
    const actions = [...document.querySelectorAll('button, a, label, div, span')]
      .filter(visible)
      .filter(item => norm(text(item)) === 'chontatca')
      .sort((a, b) => text(a).length - text(b).length);
    if (!actions.length) throw new Error('Không thấy Chọn tất cả của ' + label);
    actions[0].click();
    await sleep(900);
    button.click();
    await sleep(1400);
  }

  async function waitRows(config, timeout = 25000) {
    const expected = Array.from({length: 5}, (_, i) => 'shop' + (i + 1)).filter(key => config[key]);
    const started = Date.now();
    let signature = '', stable = 0;
    while (Date.now() - started < timeout) {
      await sleep(500);
      const state = read(config);
      const next = JSON.stringify(state.rows);
      const loading = [...document.querySelectorAll('.ant-spin-spinning, [aria-busy="true"]')].some(visible);
      stable = state.confirmed && !loading && next === signature ? stable + 1 : 0;
      signature = next;
      if (stable >= 3 && expected.length && expected.every(key => state.rows[key])) return state.rows;
    }
    throw new Error('Chưa đọc đủ dòng siêu thị trong bảng Trả chậm');
  }

  async function run(config, data, ui, done) {
    let passiveTimer = null;
    try {
      passiveTimer = setInterval(() => passiveCapture(config, ui), 800);
      ui.showToast('💳 Đang lấy Báo cáo trả chậm...', 0);
      const storedMonth = GM_getValue('tgdd_custom_report_month', 'current');
      const now = new Date();
      const expectedMonth = storedMonth === 'current' ? String(now.getMonth() + 1).padStart(2, '0') + '/' + now.getFullYear() : storedMonth;
      await callbackTask(callback => data.selectMonthDMX(expectedMonth, callback));
      for (const label of ['Vùng', 'Khu vực', 'Siêu thị']) await selectAllFilter(label);
      const cumulative = [...document.querySelectorAll('button')].find(button => visible(button) && norm(text(button)) === 'luyke');
      const view = [...document.querySelectorAll('button')].find(button => visible(button) && norm(text(button)) === 'xem');
      if (!cumulative || !view) throw new Error('Không tìm thấy nút Lũy kế hoặc Xem');
      cumulative.click();
      await sleep(500);
      view.click();
      const rows = await waitRows(config);
      save(rows);
      ui.showToast('✅ Đã lấy Trả chậm cho ' + Object.keys(rows).length + ' siêu thị', 4000);
    } catch (error) {
      console.error('[AutoBI Trả chậm 41]', error);
      ui.showToast('⚠️ Trả chậm: ' + error.message, 12000);
    } finally {
      if (passiveTimer) clearInterval(passiveTimer);
      done();
    }
  }
  let passiveSignature = '';
  async function passiveCapture(config, ui) {
    if (!location.pathname.includes('/dashboard/tra-cham')) return false;
    const state = read(config);
    const expected = Array.from({length: 5}, (_, i) => 'shop' + (i + 1)).filter(key => config[key]);
    if (!expected.length || !expected.every(key => state.rows[key])) return false;
    const signature = JSON.stringify(state.rows);
    if (signature === passiveSignature) return true;
    passiveSignature = signature;
    save(state.rows);
    GM_setValue('tgdd_installment41_status', {ok: true, at: new Date().toISOString(), rows: state.rows});
    if (ui?.showToast) ui.showToast('✅ Đã tự lưu Trả chậm: ' + expected.length + ' siêu thị', 3500);
    console.info('[AutoBI Trả chậm 41] Tự lưu bảng đang hiển thị', state.rows);
    return true;
  }
  return {number, matchShop, read, save, waitRows, selectAllFilter, passiveCapture, run};
})();

/* AutoBI 16.1.1.41 - reliable Online 18001060 capture. */
window.__AutoBIOnline40 = (() => {
  const norm = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/đ/gi, 'd').toLowerCase().replace(/[^a-z0-9]/g, '');
  const text = e => (e?.innerText || e?.textContent || '').trim();
  const visible = e => !!e && e.getClientRects().length > 0;
  const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

  function inspect(root = document) {
    let confirmedStaffTable = false;
    for (const table of root.querySelectorAll('table')) {
      const scope = table.closest('.ant-table-wrapper, .ant-table') || table;
      const headers = [...scope.querySelectorAll('thead th, thead td')].map(e => norm(e.getAttribute('title') || text(e)));
      if (!headers.some(h => h === 'nhanvien')) continue;
      const qdCol = headers.findIndex(h => ['doanhthuqd', 'doanhthuquydoi', 'dtqd', 'dtquydoi'].includes(h));
      if (qdCol < 0) continue;
      confirmedStaffTable = true;
      for (const row of table.querySelectorAll('tbody tr:not(.ant-table-measure-row)')) {
        const cells = [...row.querySelectorAll('td')];
        if (!cells.length || norm(text(cells[0])) !== 'onlineonline18001060') continue;
        const raw = text(cells[qdCol]).replace(/,/g, '').replace(/\s/g, '');
        if (!/^-?\d+(\.\d+)?$/.test(raw)) return {confirmedStaffTable, amount: null, invalid: true};
        return {confirmedStaffTable, amount: Number(raw), invalid: false};
      }
    }
    return {confirmedStaffTable, amount: null, invalid: false};
  }

  function apply(cache, key, amount) {
    const row = cache.link2?.[key];
    if (!row || !Number.isFinite(row.r) || !Number.isFinite(amount)) throw new Error('Thiếu doanh thu QĐ siêu thị');
    const previous = Number.isFinite(row.onlineExcludedQD) ? row.onlineExcludedQD : 0;
    const delta = amount - previous;
    const adjust = target => {
      if (!target || !Number.isFinite(target.r)) return;
      const before = target.r;
      target.r = before - delta;
      if (Number.isFinite(target.dtqd_dk) && before !== 0) target.dtqd_dk *= target.r / before;
      if (target.t > 0) target.dk = target.r / target.t * 100;
    };
    adjust(row);
    adjust(cache.link2.total === row ? null : cache.link2.total);
    row.grossQD = row.r + amount;
    row.onlineExcludedQD = amount;
    row.onlineExcludedAt = new Date().toISOString();
  }

  const exactButton = name => [...document.querySelectorAll('button')].find(e => visible(e) && norm(text(e)) === name);
  async function waitForStaffTable(timeout = 18000) {
    const started = Date.now();
    let stable = 0, last = '';
    while (Date.now() - started < timeout) {
      await sleep(400);
      const state = inspect();
      const signature = [...document.querySelectorAll('table tbody tr')].slice(0, 15).map(text).join('|');
      const loading = [...document.querySelectorAll('.ant-spin-spinning, [aria-busy="true"]')].some(visible);
      stable = state.confirmedStaffTable && !loading && signature && signature === last ? stable + 1 : 0;
      last = signature;
      if (state.invalid) throw new Error('Cột QĐ của Online không phải số');
      if (state.amount !== null) return state.amount;
      if (stable >= 4) return 0; // Bảng đúng đã ổn định và không có dòng Online: doanh thu Online bằng 0.
    }
    throw new Error('Bảng Nhân viên chưa tải ổn định');
  }

  async function scanShop(config, idx, waitBI, toast) {
    const key = 'shop' + idx;
    const shopName = config[key + 'Short'] || config[key] || key;
    try {
      const filter = [...document.querySelectorAll('button')].find(b => visible(b) && [...b.querySelectorAll('span')].some(e => norm(text(e)) === 'sieuthi'));
      const label = norm(text(filter));
      const tokens = [config[key], config[key + 'Short'], config['makho' + idx], config['shopCode' + idx]].map(norm).filter(Boolean);
      if (!tokens.some(t => label.includes(t))) throw new Error('Chưa xác nhận đúng bộ lọc siêu thị');

      const cumulative = exactButton('luyke');
      if (!cumulative) throw new Error('Không tìm thấy nút Lũy kế');
      cumulative.click();
      await sleep(700);
      await waitBI(15000);

      const staff = exactButton('nhanvien');
      if (!staff) throw new Error('Không tìm thấy nút Nhân viên');
      staff.click();
      await sleep(700);
      const amount = await waitForStaffTable();

      const cache = GM_getValue('tgdd_data_cache_v30', {}) || {};
      apply(cache, key, amount);
      GM_setValue('tgdd_data_cache_v30', cache);
      toast('✅ ' + shopName + ': Online QĐ ' + amount + ' triệu đã được loại', 4000);
      console.info('[AutoBI Online 40]', key, {online: amount, gross: cache.link2[key].grossQD, net: cache.link2[key].r});
    } catch (error) {
      console.error('[AutoBI Online 40]', key, error);
      toast('⚠️ Online ' + shopName + ': ' + error.message, 10000);
      await sleep(3500);
    }
  }
  return {inspect, apply, waitForStaffTable, scanShop};
})();

/* AutoBI 16.1.1.44 - fast Realtime V1 collection.
 * Keeps the normal filter/navigation pipeline, but scans Online only and skips
 * staff detail, health-category expansion and per-shop competition staff. */
window.__AutoBIFastRealtime43 = (() => {
  const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
  const enabled = () => !!(GM_getValue('tgdd_last_run_options', {}) || {}).fastRealtime;

  async function finishRevenue(config, done, ui) {
    if (!enabled()) return false;
    const health = window.__AutoBIHealthPerShop;
    const online = window.__AutoBIOnline40;
    try {
      const shops = [];
      for (let i = 1; i <= 5; i++) if (config && config['shop' + i]) shops.push(i);
      for (let pos = 0; pos < shops.length; pos++) {
        const idx = shops[pos];
        const name = config['shop' + idx + 'Short'] || config['shop' + idx] || ('shop' + idx);
        ui.showToast('⚡ Realtime nhanh [' + (pos + 1) + '/' + shops.length + ']: loại doanh thu Online ' + name, 2500);
        const selected = await health.selectSingleShop(config, idx);
        if (!selected.ok) {
          console.warn('[AutoBI Fast RT 43] Không chọn được', name, selected.reason);
          continue;
        }
        await online.scanShop(config, idx, health.waitBI, ui.showToast.bind(ui));
        await sleep(200);
      }
      await health.restoreAllShops();
    } catch (error) {
      console.error('[AutoBI Fast RT 43] Online scan error', error);
      ui.showToast('⚠️ Realtime nhanh: ' + error.message, 8000);
    }
    ui.showToast('✅ Đã đủ dữ liệu Doanh thu Realtime/Lũy kế', 1800);
    if (done) done();
    return true;
  }

  function finishCompetition(done, ui) {
    if (!enabled()) return false;
    ui.showToast('✅ Đã đủ dữ liệu Thi đua Realtime/Lũy kế', 1800);
    if (done) done();
    return true;
  }

  return {enabled, finishRevenue, finishCompetition};
})();

